public class Severidad {
	//Aquí entrá el tipo que decía
    private int tipo;
    private String nombre;
    private int prioridad;
    private int plazo;
    private double creditoHora;


    // Constructor vacio
    public Severidad() {
        tipo = 0;
        nombre = "";
        prioridad = 0;
        plazo = 0;
        creditoHora = 0;
    }


    // Constructor completo
    public Severidad(int tipo, String nombre, int prioridad, int plazo, double creditoHora) {
        this.tipo = tipo;
        this.nombre = nombre;
        this.prioridad = prioridad;
        this.plazo = plazo;
        this.creditoHora = creditoHora;
    }


    // Getters
    public int getTipo() {
        return tipo;
    }

    public String getNombre() {
        return nombre;
    }

    public int getPrioridad() {
        return prioridad;
    }

    public int getPlazo() {
        return plazo;
    }

    public double getCreditoHora() {
        return creditoHora;
    }


    // toString
    @Override
    public String toString() {
        return "Tipo: " + tipo
                + "\nNombre: " + nombre
                + "\nPrioridad: " + prioridad
                + "\nPlazo de atencion: " + plazo + " horas"
                + "\nCredito por hora: Q" + String.format("%.2f", creditoHora);
    }
}
